PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_epochs(epoch INTEGER PRIMARY KEY,parent_epoch INTEGER,root_hash TEXT NOT NULL,committed_at TEXT NOT NULL,writer_node TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'CURRENT');
CREATE TABLE IF NOT EXISTS published_surface(surface_key TEXT PRIMARY KEY CHECK(surface_key='CURRENT'),unified_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,materialization_epoch INTEGER NOT NULL,contract_sha256 TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('CURRENT','DEGRADED','CONFLICT','STALE')),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_imports(import_id TEXT PRIMARY KEY,domain TEXT NOT NULL,source_ref TEXT NOT NULL,source_commit TEXT,evidence_class TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,content_hash TEXT,imported_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entities(entity_id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS semantic_records(record_id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES entities(entity_id),predicate TEXT NOT NULL,object_text TEXT,object_ref TEXT REFERENCES entities(entity_id),epistemic_class TEXT NOT NULL,confidence REAL,epoch INTEGER NOT NULL,status TEXT NOT NULL,provenance_clay TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_semantic_lookup ON semantic_records(subject_id,predicate,status);
CREATE TABLE IF NOT EXISTS semantic_dependencies(dependency_id TEXT PRIMARY KEY,parent_ref TEXT NOT NULL,child_ref TEXT NOT NULL,relation TEXT NOT NULL,confidence REAL NOT NULL,evidence_class TEXT NOT NULL,provenance_clay TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_dep_parent ON semantic_dependencies(parent_ref,status);
CREATE INDEX IF NOT EXISTS idx_dep_child ON semantic_dependencies(child_ref,status);
CREATE TABLE IF NOT EXISTS materialized_neighborhoods(cue_ref TEXT NOT NULL,unified_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,materialization_epoch INTEGER NOT NULL,refs_clay TEXT NOT NULL,closure_hash TEXT NOT NULL,bounded_count INTEGER NOT NULL,rebuild_recipe_clay TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(cue_ref,materialization_epoch));
CREATE INDEX IF NOT EXISTS idx_materialized_current ON materialized_neighborhoods(cue_ref,materialization_epoch DESC);
CREATE TABLE IF NOT EXISTS clay_semantic_signatures(unit_ref TEXT PRIMARY KEY,contract_sha256 TEXT NOT NULL,semantic_signature_clay TEXT NOT NULL,dependency_signature_clay TEXT NOT NULL,effect_signature_clay TEXT NOT NULL,authority_signature_clay TEXT NOT NULL,provenance_signature_clay TEXT NOT NULL,hyperposition_signature_clay TEXT NOT NULL,invalidation_signature_clay TEXT NOT NULL,projection_recipe_clay TEXT NOT NULL,rebuild_recipe_clay TEXT NOT NULL,status TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organ_registry(organ_id TEXT PRIMARY KEY,canonical_name TEXT NOT NULL,functional_role TEXT NOT NULL,current_realization TEXT NOT NULL,lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN ('EXPLICIT','FUSED','EMERGENT_DISTRIBUTED','HISTORICAL_FAILURE_LINEAGE')),deletable INTEGER NOT NULL DEFAULT 0 CHECK(deletable=0),lineage_ref TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS rae_organ_delete_forbidden BEFORE DELETE ON organ_registry BEGIN SELECT RAISE(ABORT,'ORGAN_DELETE_FORBIDDEN'); END;
CREATE TABLE IF NOT EXISTS possibility_frames(frame_id TEXT PRIMARY KEY,cycle_id TEXT,realized_state_ref TEXT NOT NULL,constraints_clay TEXT NOT NULL,generative_map_ref TEXT NOT NULL,source_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hyperpositions(hyperposition_id TEXT PRIMARY KEY,frame_id TEXT NOT NULL REFERENCES possibility_frames(frame_id),subject_ref TEXT NOT NULL,context_clay TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('OPEN','PARTIALLY_RESOLVED','SELECTED','EXPIRED','REOPENED')),evidence_status TEXT NOT NULL,uncertainty REAL,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS hyperposition_alternatives(alternative_id TEXT PRIMARY KEY,hyperposition_id TEXT NOT NULL REFERENCES hyperpositions(hyperposition_id) ON DELETE CASCADE,lane TEXT NOT NULL CHECK(lane IN ('KNOWN','ANALOGOUS','COUNTERINTUITIVE','EMERGENT_NOVEL')),semantic_ref TEXT NOT NULL,proposition_clay TEXT NOT NULL,fit REAL NOT NULL,novelty REAL NOT NULL,evidence REAL NOT NULL,risk REAL NOT NULL,admissibility_state TEXT NOT NULL,provenance_clay TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gwt_episodes(episode_id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL,candidate_set_hash TEXT NOT NULL,selected_alternative_id TEXT,competition_margin REAL,ignition REAL NOT NULL,addressable_receivers INTEGER NOT NULL,source_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gwt_receiver_receipts(receipt_id TEXT PRIMARY KEY,episode_id TEXT NOT NULL REFERENCES gwt_episodes(episode_id) ON DELETE CASCADE,receiver TEXT NOT NULL,addressable INTEGER NOT NULL,delivered INTEGER NOT NULL,reconstructed INTEGER NOT NULL,uptake INTEGER NOT NULL,used INTEGER NOT NULL,local_effect INTEGER NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS receiver_stage_guard BEFORE INSERT ON gwt_receiver_receipts WHEN NEW.used=1 AND (NEW.delivered=0 OR NEW.reconstructed=0 OR NEW.uptake=0) BEGIN SELECT RAISE(ABORT,'GWT_USE_REQUIRES_DELIVERY_RECONSTRUCTION_UPTAKE'); END;
CREATE TRIGGER IF NOT EXISTS receiver_effect_guard BEFORE INSERT ON gwt_receiver_receipts WHEN NEW.local_effect=1 AND NEW.used=0 BEGIN SELECT RAISE(ABORT,'GWT_EFFECT_REQUIRES_USE'); END;
CREATE TABLE IF NOT EXISTS outcomes(outcome_id TEXT PRIMARY KEY,episode_id TEXT NOT NULL REFERENCES gwt_episodes(episode_id),observed_state_clay TEXT NOT NULL,verified INTEGER NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS causal_credit_receipts(credit_id TEXT PRIMARY KEY,target_ref TEXT NOT NULL,intervention_id TEXT,outcome_id TEXT,credit_class TEXT NOT NULL,weight REAL NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reentry_receipts(reentry_id TEXT PRIMARY KEY,outcome_id TEXT NOT NULL REFERENCES outcomes(outcome_id),from_episode_id TEXT NOT NULL,to_cycle_id TEXT NOT NULL,truth_class TEXT NOT NULL CHECK(truth_class IN ('TRUTHFUL_PROVENANCE','SHUFFLED','BROKEN_PROVENANCE','NONE')),causal_credit_class TEXT NOT NULL CHECK(causal_credit_class IN ('DIRECT_RECEIPT','PATH_SUPPORTED','CORRELATED_ONLY','NONE')),causal_credit_ref TEXT,receiver_closure INTEGER NOT NULL CHECK(receiver_closure IN (0,1)),delta_clay TEXT NOT NULL,applied INTEGER NOT NULL CHECK(applied IN (0,1)),evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS reentry_credit_guard BEFORE INSERT ON reentry_receipts WHEN NEW.applied=1 AND NEW.causal_credit_class NOT IN ('DIRECT_RECEIPT','PATH_SUPPORTED') BEGIN SELECT RAISE(ABORT,'REENTRY_STRONG_CAUSAL_CREDIT_REQUIRED'); END;
CREATE TRIGGER IF NOT EXISTS reentry_closure_guard BEFORE INSERT ON reentry_receipts WHEN NEW.applied=1 AND NEW.receiver_closure!=1 BEGIN SELECT RAISE(ABORT,'REENTRY_RECEIVER_CLOSURE_REQUIRED'); END;
CREATE TRIGGER IF NOT EXISTS reentry_verified_outcome_guard BEFORE INSERT ON reentry_receipts WHEN NEW.applied=1 AND NOT EXISTS(SELECT 1 FROM outcomes o WHERE o.outcome_id=NEW.outcome_id AND o.verified=1) BEGIN SELECT RAISE(ABORT,'REENTRY_VERIFIED_OUTCOME_REQUIRED'); END;
CREATE TABLE IF NOT EXISTS intervention_specs(intervention_id TEXT PRIMARY KEY,episode_id TEXT,intervention_class TEXT NOT NULL,specification_clay TEXT NOT NULL,matched_control_ref TEXT,predicted_effect_clay TEXT NOT NULL,rollback_clay TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS replay_receipts(replay_id TEXT PRIMARY KEY,intervention_id TEXT NOT NULL REFERENCES intervention_specs(intervention_id),episode_id TEXT,model_output_hash TEXT,pre_state_hash TEXT NOT NULL,post_state_hash TEXT NOT NULL,observed_effect_clay TEXT NOT NULL,control_effect_clay TEXT NOT NULL,result_hash TEXT NOT NULL,evidence_status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS estimator_versions(estimator_id TEXT PRIMARY KEY,estimator_family TEXT NOT NULL,version TEXT NOT NULL,configuration_clay TEXT NOT NULL,assumptions_clay TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS measurement_receipts(measurement_id TEXT PRIMARY KEY,measurement_kind TEXT NOT NULL,episode_id TEXT,state_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,intervention_id TEXT,estimator_id TEXT,source_hashes_clay TEXT NOT NULL,value_clay TEXT NOT NULL,result_hash TEXT NOT NULL,evidence_status TEXT NOT NULL,authority_effect TEXT NOT NULL DEFAULT 'NONE',created_at TEXT NOT NULL,FOREIGN KEY(intervention_id) REFERENCES intervention_specs(intervention_id),FOREIGN KEY(estimator_id) REFERENCES estimator_versions(estimator_id));
CREATE TRIGGER IF NOT EXISTS measurement_no_authority BEFORE INSERT ON measurement_receipts WHEN NEW.authority_effect!='NONE' BEGIN SELECT RAISE(ABORT,'MEASUREMENT_CANNOT_MINT_AUTHORITY'); END;
CREATE TABLE IF NOT EXISTS emergence_readouts(readout_id TEXT PRIMARY KEY,episode_id TEXT NOT NULL REFERENCES gwt_episodes(episode_id),measurement_contract_version TEXT NOT NULL,integration_clay TEXT NOT NULL,interaction_clay TEXT NOT NULL,directed_flow_clay TEXT NOT NULL,macro_causality_clay TEXT NOT NULL,dynamics_clay TEXT NOT NULL,topology_clay TEXT NOT NULL,control_clay TEXT NOT NULL,epistemic_clay TEXT NOT NULL,cost_shadow_clay TEXT NOT NULL,evidence_status TEXT NOT NULL,provenance_refs_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS emergence_gate_receipts(gate_id TEXT PRIMARY KEY,subject_ref TEXT NOT NULL,state_adequacy TEXT NOT NULL,receiver_use INTEGER NOT NULL,truthful_reentry INTEGER NOT NULL,lesion_effect REAL,rescue_recovery REAL,shuffle_delta REAL,ood_transfer REAL,macro_advantage REAL,cost_shadow REAL,verdict TEXT NOT NULL CHECK(verdict IN ('OPEN','ABSTAIN_STATE_INADEQUATE','REJECTED','SUPPORTED_FUNCTIONAL_PATTERN')),evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS control_update_receipts(update_id TEXT PRIMARY KEY,target_ref TEXT NOT NULL,prior_policy_hash TEXT NOT NULL,candidate_policy_clay TEXT NOT NULL,matched_control_ref TEXT NOT NULL,causal_credit_ref TEXT NOT NULL,ood_state TEXT NOT NULL,rollback_clay TEXT NOT NULL,promotion_state TEXT NOT NULL CHECK(promotion_state IN ('STAGED','PROMOTED','ROLLED_BACK','REJECTED')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS loop_regime_readouts(regime_id TEXT PRIMARY KEY,episode_id TEXT,feedback_gain REAL NOT NULL,ignition_occupancy REAL NOT NULL,synchrony_proxy REAL NOT NULL,dimensionality_proxy REAL NOT NULL,hub_collapse_proxy REAL NOT NULL,verdict TEXT NOT NULL CHECK(verdict IN ('UNDERCOUPLED','ADAPTIVE','OVERCOUPLED_TRIPWIRE')),evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS readout_projector_views(view_id TEXT PRIMARY KEY,episode_id TEXT NOT NULL,source_receipts_clay TEXT NOT NULL,bounded_summary_clay TEXT NOT NULL,authority_class TEXT NOT NULL CHECK(authority_class='READ_ONLY_OBSERVATION'),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS perception_io_contracts(channel_id TEXT PRIMARY KEY,input_authority TEXT NOT NULL,output_authority TEXT NOT NULL,unknown_policy TEXT NOT NULL,conflict_policy TEXT NOT NULL,reentry_policy TEXT NOT NULL,physical_claim_status TEXT NOT NULL,evidence_ref TEXT NOT NULL,status TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS legacy_conservation_receipts(receipt_id TEXT PRIMARY KEY,source_ref TEXT NOT NULL,cognitive_organs_exact INTEGER,technical_identities_exact INTEGER,historical_slots_measured INTEGER,unresolved_opaque INTEGER,claim_boundary TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claycode_contract_receipts(receipt_id TEXT PRIMARY KEY,compiler_ref TEXT NOT NULL,grammar_ref TEXT NOT NULL,contract_version TEXT NOT NULL,software_status TEXT NOT NULL,physical_release_status TEXT NOT NULL,semantic_contract_clay TEXT NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
